    public static void Seed(CrmDbContext db)
    {
        if (db.Activities.Any())
        {
            return;
        }

        var contactIds = db.Contacts.ToDictionary(c => c.ContactRef, c => c.Id);

        foreach (var row in Rows)
        {
            db.Activities.Add(new Activity(
                contactIds[$"C-{row.Contact:D5}"],
                row.Type,
                row.Subject,
                row.Notes,
                DateTimeOffset.Parse(row.OccurredAt)));
        }

        db.SaveChanges();
    }
}
